#include <vector>
static int copies = 0;
struct CTextureMorphMap {
    std::vector<unsigned long> Data; bool Dirty;
    CTextureMorphMap() : Dirty(false) { }
    CTextureMorphMap(const CTextureMorphMap& o) : Data(o.Data), Dirty(o.Dirty) { ++copies; }
